"""ME-REVISE-6: the figure PDFs regenerated by the build differ from version 6's by bytes (matplotlib stamps a creation date);
show that their decoded page content streams are equal.

    python -B revision6/fig_streams.py <old figs dir> <new figs dir> [--json out.json]        (WSL venv with PyMuPDF)
"""
import hashlib
import json
import os
import sys

import fitz


def streams(p):
    d = fitz.open(p)
    return [hashlib.sha256(pg.read_contents()).hexdigest() for pg in d]


old, new = sys.argv[1], sys.argv[2]
res = {}
for f in sorted(os.listdir(new)):
    if f.endswith(".pdf"):
        a, b = streams(os.path.join(old, f)), streams(os.path.join(new, f))
        res[f] = dict(pages=len(b), bytes_equal=open(os.path.join(old, f), "rb").read() == open(os.path.join(new, f), "rb").read(),
                      streams_equal=a == b)
res["all_streams_equal"] = all(v["streams_equal"] for v in res.values())
print(json.dumps(res, indent=1))
if "--json" in sys.argv:
    open(sys.argv[sys.argv.index("--json") + 1], "wb").write((json.dumps(res, indent=1) + "\n").encode("utf-8"))
sys.exit(0 if res["all_streams_equal"] else 1)
